function assertNever(value: never): never {
    throw new Error("Unexpected value");
}

type State =
    | { type: "idle" }
    | { type: "loading" }
    | { type: "error"; message: string };

function render(state: State): string {
    switch (state.type) {
        case "idle":
            return "Idle";

        case "loading":
            return "Loading";

        case "error":
            return state.message;

        default:
            return assertNever(state);
    }
}
